   "id": "z2cf03268",
   "sez": "prima",
   "titolo": "La testata indipendente russa Novaya Gazeta chiude la redazione di Mosca",
   "orig": "Russia's leading independent newspaper closes after eviction",
   "lead": "Lo storico giornale investigativo russo Novaya Gazeta è stato costretto a chiudere la propria redazione a Mosca dopo essere stato sfrattato dalla sede occupata da oltre trent'anni. La testata, tra le ultime voci indipendenti rimaste nel paese a criticare l'intervento militare in Ucraina, ha spiegato che le autorità l'hanno classificata come agente straniero, bloccando inoltre i canali per la raccolta di donazioni. La pressione governativa e l'intimazione di rilascio dei locali hanno reso impossibile la prosecuzione delle attività nella capitale russa.",
   "more": [
    "Novaya Gazeta è uno dei più celebri organi di stampa indipendenti nati in Russia dopo la fine dell'Unione Sovietica. Negli anni ha pagato un prezzo elevatissimo per le sue inchieste sulla corruzione e sui conflitti, con diversi suoi giornalisti assassinati, tra cui Anna Politkovskaja nel 2006, ricevendo anche il premio Nobel per la pace."
   ],
