   "id": "z920262bf",
   "sez": "mondo",
   "titolo": "Poliziotti a processo in Francia per l'aggressione al produttore Michel Zecler",
   "orig": "French police officers on trial over beating of black man they accused of not wearing Covid mask",
   "lead": "A Parigi tre agenti di polizia sono comparsi in tribunale con l'accusa di aver aggredito nel 2020 il produttore musicale nero Michel Zecler, fermato originariamente con la contestazione di non indossare la mascherina protettiva durante le restrizioni per la pandemia. L'episodio, ripreso all'epoca da telecamere di videosorveglianza, suscitò una forte ondata di indignazione nell'opinione pubblica sul tema della violenza delle forze dell'ordine. Il processo rappresenta uno dei rari casi di presunti abusi di polizia a giungere a dibattimento. Lo riferisce The Guardian.",
   "more": [
    "L'uso della forza da parte dei corpi di polizia è un argomento di forte dibattito in Francia, dove associazioni civiche e ricercatori denunciano da tempo condotte discriminatorie, mentre i sindacati di polizia e le istituzioni difendono l'operato complessivo degli agenti sottolineando la difficoltà degli interventi operativi."
   ],
