   "id": "z28234baa",
   "sez": "ambiente",
   "titolo": "Inondazioni improvvise e violente tempeste colpiscono il nord dell'Iraq",
   "orig": "Deadly floods hit Iraq as thunderstorms sweep across region",
   "lead": "Una serie di violenti temporali ha colpito il nord dell'Iraq e diverse aree del vicino Iran, provocando devastanti inondazioni improvvise che hanno causato vittime e ingenti danni materiali. La città di Erbil è risultata tra le più danneggiate: le precipitazioni hanno superato le previsioni meteorologiche raggiungendo circa 80 millimetri d'acqua in poco tempo, allagando strade, abitazioni e attività commerciali. Le autorità locali sono intervenute per gestire l'emergenza idrica nei quartieri sommersi dal fango. Lo riferisce The Guardian.",
   "more": [
    "Eventi meteorologici estremi come alluvioni lampo colpiscono con frequenza crescente le aree urbane del Medio Oriente. Il terreno arido fatica ad assorbire quantità elevate di pioggia concentrate in poche ore, mentre i sistemi fognari e di drenaggio cittadini si rivelano spesso insufficienti a contenere tali portate."
   ],
