   "id": "zb9d0f1ad",
   "sez": "mondo",
   "titolo": "Forze governative yemenite avanzano mentre riprendono gli attacchi houthi al confine",
   "orig": "Yemen government forces claim new advances as Houthi border attacks resume",
   "lead": "In Yemen le forze governative hanno annunciato nuovi progressi territoriali su diversi fronti strategici, mentre si registra una recrudescenza degli attacchi transfrontalieri condotti dai ribelli houthi. I combattimenti si sono intensificati nelle aree di contatto, segnando una ripresa delle ostilità lungo i confini e riaccendendo gli scontri armati tra le fazioni contrapposte che si contendono il controllo delle vie di comunicazione e dei principali snodi del paese. Lo riferisce Al Jazeera.",
   "more": [
    "Il conflitto in Yemen dura da circa un decennio e vede contrapposti il governo riconosciuto a livello internazionale e il movimento armato degli houthi. Le ostilità hanno generato una gravissima crisi umanitaria, coinvolgendo anche attori regionali a sostegno dei due schieramenti."
   ],
