   "id": "ze9578c77",
   "sez": "italia",
   "titolo": "Il Consiglio dei ministri approva il decreto Bollette con sgravi per l'energia",
   "orig": "Il Cdm approva il decreto legge Bollette. Pichetto: '15 euro in meno al megawattora'",
   "lead": "Il Consiglio dei ministri ha approvato il decreto legge Bollette contenente misure per la riduzione dei costi energetici per famiglie e imprese. Il ministro dell'Ambiente e della Sicurezza energetica Gilberto Pichetto Fratin ha annunciato che il provvedimento porterà a uno sgravio stimato in 15 euro in meno al megawattora a partire da gennaio, definendo la decisione un primo passo concreto a sostegno del sistema produttivo e dei consumatori sul fronte delle forniture elettriche. Lo riferisce ANSA.",
   "more": [
    "Il costo dell'energia incide direttamente sulla spesa quotidiana delle famiglie e sulla competitività delle aziende industriali. Negli ultimi anni i governi europei sono intervenuti a più riprese per mitigare gli effetti dei rincari sul mercato all'ingrosso, riducendo oneri di sistema o introducendo agevolazioni fiscali sulle forniture."
   ],
