   "id": "z8b188ebd",
   "sez": "dibattito",
   "titolo": "Gli studenti protestano in Parlamento contro i fondi della manovra economica",
   "orig": "Gli studenti in Parlamento: 'Non è una manovra per giovani'",
   "lead": "Davanti alle commissioni Bilancio del Parlamento italiano le associazioni studentesche Unione degli Universitari e Rete degli Studenti Medi hanno contestato la legge di bilancio in discussione. Secondo i rappresentanti degli studenti la manovra non tutela le giovani generazioni poiché gli stanziamenti specifici non raggiungono i 600 milioni di euro, cifra considerata largamente insufficiente per sostenere il diritto allo studio e gli alloggi. Il dibattito verte sulla quantità di risorse pubbliche da destinare all'istruzione e alle politiche giovanili rispetto agli altri capitoli di spesa pubblica. Lo riferisce ANSA.",
   "more": [
    "La legge di bilancio annuale stabilisce la ripartizione dei fondi statali tra i diversi ministeri e settori della società civile. Le organizzazioni universitarie e scolastiche chiedono regolarmente interventi strutturali per borse di studio, trasporti e sostegno contro il caro affitti, lamentando divari storici rispetto alla spesa per l'istruzione di altri paesi dell'Unione europea."
   ],
