   "id": "z7a2f7d52",
   "sez": "prima",
   "titolo": "A Bria rincara l'olio alimentare a causa della carenza di carburante",
   "orig": "Centrafrique : Hausse du prix de l’huile de cuisine à Bria sur fond de pénurie de carburant",
   "lead": "Nella città di Bria, situata nella prefettura dell'Haute-Kotto nella Repubblica Centrafricana, si registra un forte aumento del prezzo dell'olio da cucina sui mercati locali, provocato dalla grave carenza di carburante che sta paralizzando i trasporti nella regione. La mancanza di benzina e gasolio ha causato ripercussioni a catena sulla disponibilità dei beni di prima necessità, facendo lievitare i costi commerciali dei contenitori da 25 litri nelle botteghe del centro urbano. Lo riferisce Radio Ndeke Luka.",
   "more": [
    "La Repubblica Centrafricana affronta ricorrenti difficoltà logistiche legate all'approvvigionamento di combustibili, importati quasi interamente attraverso rotte fluviali o terrestri complesse. Quando il carburante scarseggia, i costi di trasporto delle merci deperibili e degli alimenti di base salgono repentinamente nei mercati periferici."
   ],
