   "id": "zc60f752a",
   "sez": "mondo",
   "titolo": "Identificate tracce fossili di globuli rossi in un osso di dinosauro di 115 milioni di anni",
   "orig": "Traces of 115-million-year-old red blood cells found in dinosaur bone",
   "lead": "Un gruppo di ricercatori ha scoperto strutture microscopiche assimilabili a globuli rossi all'interno del fossile dell'arto di un dinosauro rinvenuto in Brasile e risalente a circa 115 milioni di anni fa. I residui cellulari sono stati individuati all'interno di minuscoli canali ossei conservati nella pietra. La scoperta fornisce una prova scientifica rilevante sulla possibilità che elementi biologici legati al sangue possano preservarsi all'interno dei resti fossili per decine di milioni di anni. Lo riferisce Daily News Egypt.",
   "more": [
    "Fino a pochi anni fa la paleontologia riteneva che i tessuti molli e le molecole organiche non potessero sopravvivere ai processi di mineralizzazione geologica per più di pochi milioni di anni. Il miglioramento delle tecniche di microscopia avanzata ha permesso di svelare residui biologici insospettati nei reperti fossili."
   ],
