   "id": "zb99ff9c0",
   "sez": "cultura",
   "titolo": "Alex Garland prepara l'adattamento cinematografico del videogioco Elden Ring",
   "orig": "Alex Garland’s Elden Ring adaptation is on course to be Hollywood’s goriest ever fantasy movie",
   "lead": "Il regista britannico Alex Garland è al lavoro per portare sul grande schermo l'adattamento del popolare videogioco Elden Ring, in quello che viene preannunciato come uno dei film fantasy più cruenti mai prodotti dall'industria hollywoodiana. Il progetto gode di un consistente budget e di grande attesa da parte del pubblico, sebbene la critica si interroghi sulla capacità di trasporre la complessità e l'atmosfera narrativa del titolo originale senza ripetere gli errori di celebri precedenti adattamenti cinematografici del genere. Lo riferisce The Guardian.",
   "more": [
    "Elden Ring è un celebre videogioco di ruolo d'azione sviluppato dallo studio giapponese FromSoftware in collaborazione con lo scrittore George R.R. Martin. Il settore cinematografico guarda sempre più spesso ai franchise del mondo videoludico per attirare nuove fasce di pubblico nelle sale mondiali."
   ],
