   "id": "zda90e375",
   "sez": "economia",
   "titolo": "Merz minaccia di bloccare il bilancio UE senza accordo sui fondi a Kiev",
   "orig": "No deal on Ukraine aid? Then no deal on EU budget, Merz says",
   "lead": "Il cancelliere tedesco Friedrich Merz ha vincolato l'approvazione del bilancio pluriennale dell'Unione Europea al raggiungimento di un'intesa sul nuovo pacchetto di aiuti da 45 miliardi di euro a favore dell'Ucraina. In una lettera indirizzata al presidente del Consiglio europeo António Costa, Merz ha ribadito che il supporto a Kiev costituisce un pilastro indivisibile della sicurezza europea, avvertendo che Berlino non concederà il proprio consenso ai conti comunitari per il periodo successivo senza garanzie precise sui finanziamenti congiunti a lungo termine. Lo riferisce Euronews.",
   "more": [
    "Il quadro finanziario pluriennale dell'Unione Europea richiede l'approvazione unanime di tutti gli stati membri per essere varato. Il bilancio stabilisce i massimali di spesa comunitaria per diversi anni, coprendo sia le politiche tradizionali sia le linee di assistenza finanziaria e militare destinate ai partner esterni."
   ],
