   "id": "z7bbf29b8",
   "sez": "organizzazioni",
   "titolo": "Il Consiglio UE estende di due anni la missione di assistenza militare all'Ucraina",
   "orig": "Ukraine: Council extends EU Military Assistance Mission mandate for two years",
   "lead": "Il Consiglio dell'Unione europea ha deliberato la proroga ufficiale per altri due anni del mandato della missione di assistenza militare comunitaria a sostegno delle forze armate ucraine. Con questo provvedimento formale, le attività europee di addestramento, supporto tecnico e cooperazione a beneficio del personale militare di Kiev proseguiranno fino al 15 novembre 2028, confermando l'impegno istituzionale a lungo termine delle capitali europee per la difesa e la sicurezza dell'Ucraina. Lo riferisce il Consiglio dell'Unione europea.",
   "more": [
    "La missione di assistenza militare dell'Unione Europea (EUMAM Ukraine) è stata istituita per fornire formazione specializzata e addestramento operativo alle truppe ucraine all'interno del territorio europeo, coordinando i contributi dei diversi stati membri nel contesto del conflitto con la Russia."
   ],
