   "id": "z35df4839",
   "sez": "salute",
   "titolo": "In Nuova Zelanda debutta la nuova figura professionale dell'assistente medico",
   "orig": "Explainer: What are physician associates, and how might they change health care?",
   "lead": "Il sistema sanitario della Nuova Zelanda sta introducendo la figura professionale degli assistenti medici (physician associates), operatori sanitari qualificati chiamati a collaborare a stretto contatto con i dottori per alleggerire i carichi di lavoro nelle cliniche e negli ospedali. La novità punta a migliorare l'accesso alle cure e a ridurre i tempi di attesa per le visite di base, aprendo al contempo un dibattito sulle competenze specifiche, i percorsi formativi necessari e il tipo di mansioni cliniche che questi profili possono svolgere in autonomia. Lo riferisce RNZ.",
   "more": [
    "Gli assistenti medici sono professionisti formati per svolgere visite, raccogliere anamnesi e supportare diagnosi sotto la supervisione di un medico abilitato. Questa categoria, già ampiamente radicata nei sistemi sanitari statunitense e britannico, risponde alla carenza strutturale di personale medico generale."
   ],
