   "titolo": "Pitchfork pubblica la lista dei cento migliori album indie rock della storia",
   "orig": "La classifica dei 100 migliori dischi indie rock di tutti i tempi secondo Pitchfork",
   "lead": "La testata musicale Pitchfork ha dato alle stampe una vasta classifica dedicata ai cento migliori dischi indie rock di tutti i tempi, un'iniziativa editoriale ambiziosa destinata a riaccendere le discussioni tra appassionati e critici del settore. La redazione ha affrontato la complessa definizione storica ed estetica del genere, tracciando l'evoluzione decennale della musica indipendente attraverso le opere più influenti e innovative che hanno segnato il panorama discografico internazionale e il gusto di diverse generazioni di ascoltatori. Lo riferisce OndaRock.",
   "more": [
    "Il termine indie rock nasce per indicare la musica prodotta e distribuita da etichette discografiche indipendenti al di fuori delle grandi multinazionali del disco. Negli anni Novanta e Duemila il concetto si è trasformato in un genere musicale riconoscibile, caratterizzato da specifici stili chitarristici e attitudini compositive."
   ],
