   "id": "z791e58f3",
   "sez": "viaggi",
   "titolo": "A Londra apre nel 2027 un hotel di lusso ispirato a Alexander McQueen",
   "orig": "One of 2027’s most anticipated hotels owes its soul to a fashion icon",
   "lead": "L'eredità del celebre stilista Alexander McQueen costituirà una delle principali attrazioni di una nuova struttura alberghiera di lusso, la cui apertura a Londra è prevista per il 2027. Il progetto alberghiero mira a integrare elementi ispirati alla visione creativa e allo stile dell'iconico designer britannico, scomparso nel 2010, rendendolo un punto di riferimento per l'ospitalità e il design nella capitale del Regno Unito. L'iniziativa celebra così l'impatto culturale e artistico lasciato dalla casa di moda nel panorama internazionale. Lo riferisce Sydney Morning Herald.",
   "more": [
    "Alexander McQueen è stato uno dei designer più influenti e visionari della moda contemporanea britannica. Fondatore dell'omonima maison e già direttore creativo di Givenchy, ha ridefinito l'estetica sartoriale con sfilate teatrali e concetti d'avanguardia. La sua eredità continua a influenzare non solo la moda globale, ma anche l'architettura d'interni e l'industria dell'accoglienza di alto livello."
   ],
