   "id": "zc426377f",
   "sez": "cultura",
   "titolo": "Carsten Höller installa il suo scivolo più grande a Città del Messico",
   "orig": "Carsten Höller installs \"largest\" of his slides in Mexico City",
   "lead": "L'artista tedesco Carsten Höller ha completato l'installazione della versione più grande mai realizzata dei suoi celebri scivoli architettonici a Città del Messico. L'opera monumentale è stata integrata all'interno di un nuovo complesso di sviluppo urbano progettato dal prestigioso studio di architettura Sordo Madaleno. Höller, noto a livello internazionale per le sue sculture interattive che uniscono arte, dinamismo ed esperienza fisica, porta così nella capitale messicana una struttura imponente che permette ai visitatori di interagire direttamente con lo spazio architettonico attraverso il movimento e la discesa. Lo riferisce Dezeen.",
   "more": [
    "Carsten Höller è celebre nel panorama dell'arte contemporanea per le sue installazioni scultoree e monumentali scivoli tubolari in acciaio, già esposti alla Tate Modern di Londra e in altre importanti istituzioni. Le sue opere esplorano il comportamento umano e la percezione sensoriale, trasformando i fruitori in partecipanti attivi che vivono l'architettura attraverso il gioco e la discesa controllata."
   ],
