   "id": "zc1c2ade2",
   "sez": "sport",
   "titolo": "Cricket, Warner rompe il silenzio: «Tutti sapevano dell'alterazione della palla»",
   "orig": "Warner says Khawaja's ball-tampering claim '100 per cent accurate'",
   "lead": "L'ex vice capitano della nazionale australiana di cricket, David Warner, ha rotto un silenzio durato otto anni per sostenere pienamente le dichiarazioni del compagno di squadra Usman Khawaja riguardo allo scandalo dell'alterazione della palla. Warner ha confermato che l'affermazione secondo cui ogni giocatore della squadra fosse a conoscenza del piano per alterare la sfera con carta vetrata durante la partita del 2018 in Sudafrica è del tutto accurata. L'atleta ha espresso gratitudine a Khawaja per aver reso pubblica la verità, criticando al contempo le indagini condotte a suo tempo da Cricket Australia.",
   "more": [
    "Il caso del \"sandpaper gate\", scoppiato nel marzo 2018 durante un test match a Città del Capo, rappresentò uno dei momenti più bui per il cricket australiano. L'alterazione della superficie della palla è un'infrazione grave che modifica la traiettoria dei lanci. La vicenda portò alla squalifica di Warner, del capitano Steve Smith e del giocatore Cameron Bancroft, scuotendo i vertici della federazione."
   ],
