   "id": "zfcab7da0",
   "sez": "dibattito",
   "titolo": "Aumento del salario minimo in Francia: i sindacati confermano lo sciopero di novembre",
   "orig": "Subida do salário mínimo em França não afasta espectro das greves e dos protestos nas ruas",
   "lead": "In Francia si discute sull'adeguatezza dell'aumento del salario minimo deciso dal governo per sostenere il potere d'acquisto dei lavoratori. Secondo una delle principali confederazioni sindacali del Paese, l'adeguamento economico concesso rappresenta soltanto una misura minima e insufficiente rispetto al costo della vita, motivo per cui è stato confermato uno sciopero nazionale per il 17 novembre. Dal canto suo, il primo ministro francese difende il provvedimento, sostenendo che l'entità dell'aumento salariale stabilito dall'esecutivo sia calibrata per garantire la tutela e la salvaguardia dei posti di lavoro nelle imprese. Lo riferisce Público.",
   "more": [
    "Il salario minimo legale, noto in Francia come Smic, viene aggiornato periodicamente dalle autorità per adeguarlo all'inflazione e sostenere le retribuzioni più basse. Il dibattito economico contrappone solitamente le organizzazioni sindacali, che richiedono aumenti più consistenti per contrastare l'erosione del potere d'acquisto delle famiglie, e i datori di lavoro o i governi, preoccupati che incrementi troppo marcati possano appesantire il costo del lavoro e frenare le assunzioni."
   ],
