   "id": "z33e38525",
   "sez": "spazio",
   "titolo": "La NASA lancia la sfida AMPERE per sviluppare propulsori elettrici a effetto Hall",
   "orig": "NASA Advanced Mid-Power Electric Rocket Challenge",
   "lead": "La NASA ha annunciato il lancio della sfida tecnologica \"Advanced Mid-Power Electric Rocket\", denominata AMPERE Challenge, finalizzata allo sviluppo e alla dimostrazione di sistemi di propulsione elettrica avanzati. L'agenzia spaziale statunitense ha invitato le aziende commerciali del Paese a progettare propulsori a effetto Hall di potenza intermedia, compresa tra i 3 e i 7 kilowatt. Tali sistemi sono stati identificati da esperti governativi e industriali come capacità operative cruciali per future missioni satellitari commerciali, progetti di difesa ed esplorazioni spaziali a lungo raggio. Lo riferisce Nasa.",
   "more": [
    "I propulsori a effetto Hall rappresentano una tecnologia di propulsione elettrica spaziale che sfrutta campi magnetici ed elettrici per accelerare particelle di gas ionizzato, come il gas xeno, producendo spinta. Rispetto ai tradizionali motori a combustione chimica, questi sistemi richiedono una quantità significativamente inferiore di propellente, consentendo alle sonde spaziali e ai satelliti operativi di rimanere in orbita molto più a lungo."
   ],
