   "id": "zcaf98399",
   "sez": "economia",
   "titolo": "Dieci anni dalla demonetizzazione in India: un bilancio economico ancora contestato",
   "orig": "India’s demonetization: 10 years on, promises remain unfulfilled",
   "lead": "A dieci anni dall'improvvisa decisione presa nel 2016 dal governo indiano di ritirare dalla circolazione le banconote di grosso taglio, le promesse legate alla misura rimangono in gran parte disattese. L'impatto economico della demonetizzazione sul tessuto produttivo dell'India e la sua effettiva efficacia nella lotta al denaro nero e all'evasione fiscale continuano a essere oggetto di forte contestazione. Nonostante l'obiettivo dichiarato di digitalizzare i pagamenti ed estirpare la ricchezza sommersa, gli analisti e i critici evidenziano ripercussioni durature per le piccole imprese e per i lavoratori informali. Lo riferisce Deutsche Welle.",
   "more": [
    "Nel novembre 2016 il primo ministro indiano Narendra Modi annunciò a sorpresa l'annullamento immediato del valore legale delle banconote da 500 e 1.000 rupie, che costituivano l'86% del contante in circolazione. L'iniziativa mirava a combattere la corruzione e la contraffazione, ma generò prolungate carenze di liquidità e diffuse difficoltà economiche, soprattutto nelle vaste aree rurali del Paese dipendenti dal contante."
   ],
