   "id": "ze5507fa4",
   "sez": "tech",
   "titolo": "Un ragazzo crea un'app gratuita per aiutare a interpretare le emozioni nell'autismo",
   "orig": "Interpreting Autistic Cues Is Difficult, a Teen Built an App That’s Helping Hundreds of Families",
   "lead": "Un adolescente ha sviluppato autonomamente un'applicazione basata sull'apprendimento automatico per aiutare genitori e operatori a interpretare i segnali emotivi delle persone con autismo. Il giovane ha ideato il software, denominato Kora, dopo aver osservato le continue difficoltà degli adulti nel comprendere le esigenze del proprio cugino autistico. Lo strumento, completamente gratuito, conta già oltre settecento utilizzatori distribuiti in dodici Paesi e viene diffuso tramite centri terapeutici specializzati. Il programma consente ai familiari di decifrare le manifestazioni comportamentali dei ragazzi, migliorando sensibilmente la comunicazione quotidiana e il supporto all'interno delle famiglie coinvolte. Lo riferisce Good News Network.",
   "more": [
    "I disturbi dello spettro autistico comprendono una varietà di condizioni del neurosviluppo caratterizzate da peculiarità nella comunicazione, nelle interazioni sociali e nella regolazione emotiva. Le persone autistiche possono esprimere disagio o bisogni attraverso segnali verbali e non verbali complessi, spesso difficili da decodificare per chi le circonda. Gli strumenti digitali assistivi offrono un valido aiuto per facilitare la comprensione reciproca."
   ],
