   "id": "z64d96306",
   "sez": "cultura",
   "titolo": "A Milano apre la mostra dedicata a Max Bill e all'arte come innovazione",
   "orig": "Aperta dal 6 Novembre la mostra “max bill. l’arte è un problema d’innovazione”",
   "lead": "A Milano, presso la galleria Lorenzelli Arte, è aperta al pubblico la mostra intitolata \"max bill. l'arte è un problema d'innovazione\", dedicata all'opera del celebre maestro svizzero. L'esposizione prende spunto da una riflessione pronunciata da Max Bill nel 1976, nella quale l'artista definiva la creazione come un atto di responsabilità personale e identificava l'arte in un processo costante di invenzione e rinnovamento. La rassegna milanese approfondisce il rigore formale e le ricerche geometriche che hanno caratterizzato la poliedrica carriera dell'autore elvetico tra pittura, scultura e design contemporaneo. Lo riferisce AREA.",
   "more": [
    "Max Bill, allievo del Bauhaus a Dessau, è stato una figura di primo piano dell'arte concreta, dell'architettura e del graphic design del Novecento. Co-fondatore della celebre Scuola di progettazione di Ulm, ha teorizzato una fusione armonica tra pensiero matematico, chiarezza razionale e funzione estetica, influenzando generazioni di designer e artisti costruttivisti in tutta Europa."
   ],
