   "id": "z10cf1d78",
   "sez": "musica",
   "titolo": "I New Order annunciano un tour negli Stati Uniti per il 2027",
   "orig": "New Order Plot 2027 U.S. Tour",
   "lead": "La leggendaria formazione britannica New Order ha annunciato una nuova tournée negli Stati Uniti programmata per il 2027. La storica band pioniera del synth-pop e della new wave avvierà la serie di concerti attraverso le regioni meridionali americane, aprendo il tour con tre attesissime date nello stato del Texas. In queste tappe inaugurali, i musicisti di Manchester saranno accompagnati dal gruppo synth-pop Future Islands, confermato ufficialmente come gruppo di supporto per l'avvio della rassegna musicale oltreoceano. Il ritorno sui palchi statunitensi segna una nuova tappa per lo storico gruppo inglese. Lo riferisce Pitchfork.",
   "more": [
    "I New Order si formarono a Manchester nel 1980 sulle ceneri dei Joy Division, in seguito alla scomparsa del cantante Ian Curtis. La band ha rivoluzionato il panorama musicale fondendo il post-punk con la musica dance elettronica e la musica house, grazie a pietre miliari del genere come il singolo \"Blue Monday\", divenuto il vinile a dodici pollici più venduto di sempre."
   ],
