   "sez": "organizzazioni",
   "titolo": "A Vienna si apre il 15° Simposio sulle garanzie internazionali dell'AIEA",
   "orig": "Nuclear Safeguards in a Changing World – 15th Symposium on International Safeguards Opens in Vienna",
   "lead": "A Vienna si è aperta la quindicesima edizione del Simposio sulle garanzie internazionali, organizzato dall'Agenzia internazionale per l'energia atomica sotto il titolo \"Nuclear Safeguards in a Changing World\". L'incontro internazionale riunisce esperti, delegati governativi e scienziati per fare il punto sui sistemi di verifica e controllo delle attività nucleari globali di fronte alle crescenti complessità geopolitiche e alle nuove frontiere scientifiche. I partecipanti discuteranno le strategie per rafforzare la non proliferazione, modernizzare le procedure di ispezione e garantire che l'energia atomica venga impiegata esclusivamente per scopi pacifici. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "Le salvaguardie dell'AIEA sono un insieme di misure tecniche e ispezioni attraverso cui l'agenzia dell'ONU verifica che gli Stati rispettino gli obblighi del Trattato di non proliferazione nucleare. Il loro scopo primario è accertare che i materiali e gli impianti nucleari dichiarati per usi civili ed energetici non vengano deviati verso la fabbricazione di armi nucleari o ordigni esplosivi."
   ],
