   "id": "z410c8eeb",
   "sez": "dibattito",
   "titolo": "Amsterdam, la commemorazione della Notte dei cristalli riaccende il confronto su Israele",
   "orig": "Politieke boodschap bij Kristallnachtherdenking: 'Rode Lijn-protest is anti-Israël'",
   "lead": "A Amsterdam la commemorazione dell'ottantottesimo anniversario della Notte dei cristalli ha aperto un acceso confronto politico sul significato della memoria e sulla guerra in Medio Oriente. Durante la cerimonia nella Sinagoga Portoghese, il presidente dell'organizzazione ebraica CJO, Chanan Hertzberger, ha criticato la manifestazione di protesta denominata \"Linea Rossa\", definendola apertamente anti-israeliana, e ha ringraziato il leader politico Rob Jetten per non aver ceduto alle richieste degli organizzatori. I manifestanti del corteo avevano sfilato per contestare la linea diplomatica del governo olandese verso Israele, mentre Jetten ha invitato a riflettere sui parallelismi tra passato e presente.",
   "more": [
    "La Notte dei cristalli, avvenuta tra il 9 e il 10 novembre 1938, segnò una violenta ondata di pogrom antisemiti orchestrati dal regime nazista in Germania, con la distruzione di sinagoghe, negozi e arresti di massa. Nelle democrazie europee, le commemorazioni storiche dell'Olocausto si intrecciano talvolta con l'attualità geopolitica, alimentando discussioni pubbliche sui confini tra critica legittima alle azioni dei governi e tutela delle minoranze."
   ],
