   "sez": "spazio",
   "titolo": "La NASA stanzia un milione di dollari per il concorso studentesco Base Lunare",
   "orig": "La NASA destina un millón de dólares al reto estudiantil Base Lunar",
   "lead": "La NASA ha annunciato lo stanziamento di un milione di dollari per finanziare il concorso studentesco \"Base Lunar\", dedicato alla progettazione di soluzioni per future colonie umane sulla Luna. Il bando è stato presentato ufficialmente presso il complesso per visitatori del Kennedy Space Center, in Florida, nel corso di un evento pubblico di divulgazione scientifica. L'iniziativa invita studenti universitari e ricercatori emergenti a elaborare tecnologie e habitat innovativi a supporto dell'esplorazione spaziale, con l'obiettivo di stimolare l'ingegno delle nuove generazioni nell'ambito dei piani per una presenza umana permanente sul suolo lunare. Lo riferisce Nasa.",
   "more": [
    "Con il programma Artemis e i progetti di cooperazione internazionale, la NASA intende stabilire una base scientifica stabile sulla superficie lunare per preparare future missioni con equipaggio verso Marte. Coinvolgere le università attraverso gare e premi finanziari permette all'agenzia di accelerare lo sviluppo di tecnologie sostenibili per la produzione di ossigeno, l'estrazione di risorse e la schermatura dalle radiazioni."
   ],
