   "sez": "economia",
   "titolo": "Wellington, il cinema storico Penthouse a rischio chiusura per l'aumento delle tasse",
   "orig": "'Nail in the coffin': Wellington's Penthouse Cinema could face closure if council rates change",
   "lead": "A Wellington, in Nuova Zelanda, il celebre cinema storico Penthouse Cinema e diverse attività commerciali locali rischiano la chiusura definitiva a causa della proposta di riforma delle imposte municipali avanzata dal consiglio comunale. Secondo le testimonianze degli esercenti, tra cui il titolare di un bar della zona che prevede un rincaro fiscale fino a centomila dollari, il nuovo sistema impositivo rappresenterebbe un colpo insostenibile per i bilanci delle strutture indipendenti. Gli operatori economici avvertono che tali incrementi forzeranno molte attività culturali e ricreative a cessare l'attività, compromettendo il tessuto sociale cittadino. Lo riferisce RNZ.",
   "more": [
    "Le tasse municipali, note in Nuova Zelanda e nei Paesi anglosassoni come \"rates\", costituiscono la principale fonte di entrate per i consigli cittadini, utilizzata per finanziare infrastrutture, servizi pubblici e trasporti. Le modifiche ai criteri di calcolo degli estimi catastali o delle quote commerciali possono determinare forti aumenti dei costi fissi per negozi e luoghi di spettacolo indipendenti."
   ],
