   "id": "zf4902601",
   "sez": "tech",
   "titolo": "Il Brasile porta trecento startup al Web Summit di Lisbona per puntare sulla tecnologia",
   "orig": "Brasil aposta na tecnologia e quer mostrar que é mais do que \"agro\"",
   "lead": "A Lisbona, in occasione della conferenza tecnologica Web Summit, il Brasile ha promosso una vasta delegazione commerciale per dimostrare la propria competitività nell'innovazione digitale, superando la tradizionale immagine legata all'esportazione di prodotti agricoli. L'agenzia governativa ApexBrasil ha favorito la partecipazione di circa trecento startup brasiliane, giunte nella capitale portoghese con l'obiettivo di incontrare partner commerciali e attrarre investitori europei. L'iniziativa mira a diversificare i flussi dell'export nazionale e a consolidare la presenza delle imprese tecnologiche del Paese sudamericano sui mercati internazionali e dell'Unione Europea. Lo riferisce RTP.",
   "more": [
    "Il Web Summit di Lisbona è una delle maggiori conferenze mondiali dedicate a tecnologia, economia digitale e venture capital. Per i Paesi emergenti, l'evento rappresenta una vetrina strategica per attirare capitali esteri nel settore dell'innovazione, consentendo alle aziende ad alto tasso tecnologico di scalare a livello internazionale e ridurre la dipendenza economica dalle materie prime tradizionali."
   ],
