   "id": "z03c42aab",
   "sez": "cultura",
   "titolo": "Alle piramidi di Giza tornano le installazioni monumentali per Forever Is Now",
   "orig": "sculptural portals and golden guardians arrive at giza for art d’égypte",
   "lead": "Presso le millenarie piramidi di Giza, in Egitto, è stata inaugurata la sesta edizione della rassegna d'arte contemporanea \"Forever Is Now\", promossa dall'organizzazione Art D'Égypte. La mostra a cielo aperto presenta otto imponenti installazioni site-specific, tra cui portali scultorei e figure guardiane dorate, realizzate da diversi artisti internazionali che si confrontano visivamente con i celebri monumenti funerari faraonici. Le opere esposte esplorano i miti dell'antichità e il legame profondo tra memoria storica e linguaggi moderni, creando un dialogo tra il patrimonio archeologico e la scultura contemporanea internazionale. Lo riferisce Designboom.",
   "more": [
    "La piana di Giza, patrimonio mondiale dell'UNESCO, ospita le più celebri piramidi dell'antico Egitto, tra cui la Grande Piramide di Cheope e la Sfinge. Negli ultimi anni l'area archeologica è divenuta teatro di mostre d'arte contemporanea di respiro globale, con l'obiettivo di valorizzare il patrimonio millenario attraverso installazioni che rispettino la delicatezza del contesto paesaggistico e storico."
   ],
