   "id": "zf86c23bd",
   "sez": "adolescenti",
   "titolo": "Mense scolastiche in Italia: forte divario Nord-Sud sulla varietà dei cereali offerti",
   "orig": "Mense scolastiche, il divario Nord-Sud: almeno quattro cereali al mese nell’83,3% dei menù del Nord, al Sud e nelle Isole solo nel 25%",
   "lead": "In Italia emergono marcate differenze territoriali nella qualità nutrizionale dei pasti offerti nelle mense scolastiche. Secondo i dati relativi alla varietà alimentare, nel Nord del Paese l'83,3% dei menù destinati agli studenti propone almeno quattro tipologie differenti di cereali nell'arco del mese. Al contrario, la percentuale crolla drasticamente al Sud e nelle Isole, dove soltanto il 25% degli istituti scolastici garantisce la presenza di quattro cereali diversi nelle diete mensili. La rilevazione mette in luce un netto divario geografico nella cura della refezione scolastica e nell'educazione a una sana alimentazione per i giovani. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La refezione scolastica svolge un ruolo chiave nella salute dei minori e nella promozione della dieta mediterranea, ricca di varietà di cereali come farro, orzo, riso e grano integrale. Il servizio delle mense, gestito per lo più dagli enti comunali, risente spesso di disomogeneità nelle risorse economiche disponibili e nei capitolati d'appalto tra le diverse regioni d'Italia."
   ],
