   "id": "z660420c4",
   "sez": "sport",
   "titolo": "La soddisfazione di Margherita Gregoroni a Dakar 2026 e le medaglie equestri",
   "orig": "Gregoroni: “Soddisfatta di Dakar 2026, ma già concentrata sui prossimi obiettivi”",
   "lead": "Ai Giochi Olimpici Giovanili di Dakar 2026 in Senegal, l'atleta sammarinese Margherita Gregoroni ha concluso la sua partecipazione raggiungendo la finale dei 200 metri misti e vivendo l'emozione di sfilare come portabandiera della propria delegazione. Nel frattempo, nella disciplina del salto a ostacoli equestre a squadre, la cavaliera Eden Kazoum ha conquistato la medaglia di bronzo con il Team Afrique presso il Centro ippico di Diamniadio, una conquista che tuttavia non figura nel medagliere ufficiale del Senegal.",
   "more": [
    "I Giochi Olimpici Giovanili costituiscono una manifestazione multisportiva internazionale riservata agli atleti di età compresa tra i quattordici e i diciotto anni. L'edizione di Dakar 2026 rappresenta il primo evento olimpico organizzato nel continente africano, introducendo anche formule di gara a squadre miste continentali che promuovono l'integrazione tra sportivi provenienti da diverse nazioni."
   ],
