   "sez": "mondo",
   "titolo": "Spagna: il PP accetta l'Academia de Televisión per i dibattiti elettorali",
   "orig": "Última hora de la actualidad política, en directo | El PP acepta que los debates sean organizados por la Academia de Televisión",
   "lead": "A Madrid il Partido Popular ha accettato la proposta del PSOE di affidare all'Academia de Televisión l'organizzazione del dibattito a due tra i leader politici e del confronto a quattro in vista delle elezioni. I popolari ritengono che questa formula garantisca un segnale neutrale e aperto. Nel frattempo il leader del PP Alberto Núñez Feijóo ha annunciato l'intenzione di abrogare la legge sulla casa qualora andasse al governo, sostenendo che l'emergenza abitativa si risolva incrementando la costruzione di nuovi immobili.",
   "more": [
    "I dibattiti televisivi in Spagna rappresentano un momento cruciale delle campagne elettorali, tradizionalmente negoziati nei dettagli tecnici tra le principali forze politiche. La scelta di un ente neutrale come l'Academia de Televisión punta a garantire standard di trasmissione uniformi e imparziali per tutte le emittenti, evitando controversie sull'assegnazione degli spazi e dei tempi di parola ai candidati."
   ],
