   "sez": "spazio",
   "titolo": "Gala di celebrazione del programma Artemis al Kennedy Space Center della NASA",
   "orig": "Astronauts Across Generations Share the Stage",
   "lead": "Il 6 novembre 2026 presso il Visitor Complex del Kennedy Space Center a Merritt Island, in Florida, si è svolto l'Artemis Celebration Gala organizzato da Purpose Entertainment. L'evento, tenutosi alla vigilia dell'appuntamento MAX POWER della NASA, ha riunito astronauti di differenti generazioni, innovatori e visionari del settore aerospaziale per celebrare i successi del programma di esplorazione lunare e tracciare le linee guida della nuova era del volo umano nello spazio. Lo riferisce Nasa.",
   "more": [
    "Il programma Artemis della NASA punta a riportare l'essere umano sulla Luna e a stabilire una presenza sostenibile sul suolo lunare in vista delle future missioni verso Marte. Il coinvolgimento di partner privati e istituzionali è fondamentale per lo sviluppo delle tecnologie necessarie al sostentamento delle frequenti missioni abitate e alla ricerca scientifica nello spazio profondo."
   ],
