   "id": "z7688bdff",
   "sez": "ambiente",
   "titolo": "Le reti elettriche obsolete ostacolano la transizione verso le energie rinnovabili",
   "orig": "Outdated power grids a major hurdle in renewable energy transition",
   "lead": "Le reti elettriche obsolete rappresentano uno dei principali ostacoli a livello globale nella transizione dai combustibili fossili verso le fonti energetiche rinnovabili. Le infrastrutture di distribuzione più datate non possiedono infatti la capacità tecnologica necessaria per assorbire e gestire l'intera quantità di elettricità prodotta dai nuovi impianti solari ed eolici, limitando l'efficacia degli investimenti nella decarbonizzazione e rallentando il raggiungimento degli obiettivi climatici internazionali. Lo riferisce PBS NewsHour.",
   "more": [
    "La modernizzazione delle reti elettriche richiede ingenti investimenti per l'integrazione di sistemi di stoccaggio dell'energia e di tecnologie di gestione intelligente dei flussi elettrici. Senza adeguati interventi sulle infrastrutture di trasmissione, gran parte dell'energia pulita prodotta rischia di essere sprecata a causa delle limitazioni fisiche dei cavi e delle stazioni di trasformazione esistenti."
   ],
