   "titolo": "Kenya: Lydia Chelagat nominata nuova Data Commissioner del Paese",
   "orig": "President Ruto nominates Lydia Chelagat as Kenya’s next Data Commissioner",
   "lead": "A Nairobi il presidente del Kenya William Ruto ha nominato Lydia Chelagat come nuova Commissaria per i dati del Paese. L'annuncio ufficiale è stato dato lunedì 9 novembre dal portavoce del governo Charles Owino Wahong'o, il quale ha spiegato che la decisione presidenziale è giunta a seguito delle raccomandazioni formulate dalla Public Service Commission al termine delle procedure di selezione dei candidati alla guida dell'organismo di tutela della privacy. Lo riferisce Citizen Digital.",
   "more": [
    "L'autorità per la protezione dei dati personali ha il compito di vigilare sul trattamento delle informazioni digitali da parte di enti pubblici e privati. In un contesto di rapida digitalizzazione dei servizi amministrativi e finanziari, la presenza di un commissario indipendente garantisce il rispetto dei diritti dei cittadini e la conformità alle normative sulla privacy."
   ],
