   "sez": "ingegneria",
   "titolo": "Il governo britannico avvia una revisione sui costi delle infrastrutture ferroviarie",
   "orig": "Government to review cost of UK rail construction",
   "lead": "Il governo del Regno Unito ha avviato un'indagine formale per individuare le ragioni per cui i progetti di costruzione delle infrastrutture ferroviarie britanniche risultino particolarmente onerosi da realizzare rispetto alla media degli altri Paesi. I tecnici e gli esperti incaricati della revisione dovranno esaminare la pianificazione e i costi di cantiere, presentando le proprie raccomandazioni e soluzioni strategiche entro i prossimi sei mesi. Lo riferisce New Civil Engineer.",
   "more": [
    "I grandi progetti di trasporto su rotaia soffrono spesso di ritardi e sforamenti di bilancio dovuti alla complessità delle procedure autorizzative, all'adeguamento delle norme di sicurezza e all'aumento dei costi delle materie prime. Analizzare i fattori di spesa consente di migliorare la gestione dei cantieri e di ottimizzare l'impiego dei fondi pubblici per le infrastrutture future."
   ],
