   "sez": "salute",
   "titolo": "Congresso dell'American Heart Association: risultati neutri ma ricerca aperta",
   "orig": "STAT+: Heart association meeting’s readout is trending ‘neutral’",
   "lead": "L'annuale congresso dell'American Heart Association si è concluso con un bilancio complessivo di risultati clinici orientati verso la neutralità scientifica. Nonostante l'assenza di dati clamorosi nelle sperimentazioni presentate, i ricercatori e i medici specializzati confermano l'intenzione di proseguire le indagini e lo sviluppo di nuove terapie farmacologiche volte a ridurre l'infiammazione cardiovascolare e a diminuire i livelli di lipoproteina Lp(a) nei pazienti a rischio. Lo riferisce STAT.",
   "more": [
    "La lipoproteina Lp(a) è un fattore di rischio genetico indipendente per l'insorgenza di malattie cardiovascolari, come infarti e ictus, per il quale non esistono ancora trattamenti ampiamente diffusi. La ricerca farmacologica sta concentrando gli sforzi sullo sviluppo di molecole capaci di agire sia sui livelli lipidici sia sugli stati infiammatori delle arterie."
   ],
