   "titolo": "A Praga torna il Micro Praha Festival con 93 marchi di orologeria",
   "orig": "Micro Praha Festival Returns With 93 Watch Brands From 27 Countries",
   "lead": "A Praga il 28 e 29 novembre si terrà la quarta edizione del Micro Praha Festival, l'evento internazionale dedicato all'orologeria ospitato all'interno dello storico Fantův sál della stazione ferroviaria centrale. La manifestazione vedrà la partecipazione di 93 marchi indipendenti provenienti da 27 Paesi differenti. I visitatori, che potranno accedere gratuitamente previa registrazione online, avranno l'opportunità di scoprire nuove collezioni, provare i segnatempo e incontrare i produttori. Lo riferisce Prague Morning.",
   "more": [
    "I festival dedicati all'orologeria indipendente offrono una vetrina internazionale ai piccoli produttori e ai maestri artigiani che realizzano segnatempo in tiratura limitata. L'organizzazione di tali eventi all'interno di stabili storici valorizza il patrimonio architettonico cittadino e attira collezionisti e appassionati del settore da tutta Europa."
   ],
