   "sez": "ambiente",
   "titolo": "Giovani neozelandesi portano gli impatti del clima al vertice mondiale",
   "orig": "The young Kiwis heading to the world's biggest climate change gathering",
   "lead": "Tre giovani delegati neozelandesi si preparano a partecipare per la prima volta al vertice annuale sulle questioni climatiche mondiali. Durante l'assise internazionale i rappresentanti illustreranno alla vasta platea globale le conseguenze concrete e quotidiane che i cambiamenti del clima stanno causando sulle comunità locali e sul territorio della Nuova Zelanda, evidenziando le urgenze ecologiche che colpiscono i territori insulari dell'Oceano Pacifico. Lo riferisce RNZ.",
   "more": [
    "La partecipazione delle nuove generazioni ai conferenze internazionali sul clima consente di dare voce alle popolazioni più vulnerabili di fronte al riscaldamento globale. I Paesi dell'Oceania soffrono particolarmente l'innalzamento del livello dei mari e l'aumento dei fenomeni meteorologici estremi, necessitando di interventi rapidi di adattamento infrastrutturale e di riduzione delle emissioni."
   ],
