   "titolo": "Nigeria: il governatore Makinde promette sviluppo economico trainato dal turismo",
   "orig": "Makinde urges Plateau voters to reject APC, promises tourism-led economic growth",
   "lead": "A Jos, nello Stato di Plateau, il governatore dello Stato di Oyo Seyi Makinde ha tenuto un discorso durante un raduno elettorale per la campagna presidenziale dell'APM, esortando i cittadini a respingere il partito di governo APC. Durante l'evento politico il rappresentante dell'opposizione ha promesso di rilanciare l'economia e l'occupazione della regione attraverso un piano strutturato di sviluppo incentrato sulla promozione del turismo sostenibile e delle risorse territoriali. Lo riferisce Premium Times.",
   "more": [
    "Lo sviluppo del turismo interno nelle regioni della Nigeria rappresenta una risorsa strategica per diversificare l'economia nazionale, tradizionalmente dipendente dal settore petrolifero. Gli investimenti nelle infrastrutture e nella sicurezza locale sono considerati fattori chiave per attrarre visitatori e stimolare la crescita delle piccole e medie imprese nell'indotto turistico e alberghiero."
   ],
