   "titolo": "Stati Uniti: indagine federale sui veicoli Waymo per violazioni sugli scuolabus",
   "orig": "US opens probe into Waymo vehicles over school bus safety violations",
   "lead": "Negli Stati Uniti le autorità di regolamentazione hanno aperto un'indagine formale sui veicoli a guida autonoma della società Waymo per presunte violazioni delle norme di sicurezza stradale relative agli scuolabus. Gli esaminatori intendono verificare se un aggiornamento del software di bordo non sia riuscito a impedire alle auto senza conducente di sorpassare gli scuolabus fermi con le luci rosse lampeggianti attive. Lo riferisce The Straits Times.",
   "more": [
    "La tecnologia di guida autonoma si basa su sensori, telecamere e algoritmi per la rilevazione della segnaletica e degli ostacoli lungo le strade. Il mancato rispetto dei dispositivi di arresto degli scuolabus rappresenta un rischio critico per l'incolumità dei minori, spingendo gli enti di controllo a verificare la sicurezza dei codici di programmazione."
   ],
