   "id": "za6688728",
   "sez": "ingegneria",
   "titolo": "Ohio: inchiesta addebita a Enbridge l'esplosione della condotta di gas",
   "orig": "Probe Blames Enbridge for Ohio Gas Line Blast That Destroyed Three Houses",
   "lead": "In Ohio gli investigatori incaricati delle perizie tecniche hanno attribuito alla società Enbridge la responsabilità dell'esplosione di una condotta di gas che ha distrutto tre abitazioni e danneggiato decine di case circostanti. Secondo le ricostruzioni ufficiali, la tracciatura del gasdotto fornita all'impresa esecutrice dei lavori presentava un errore di posizionamento di circa 70 centimetri, provocando una scalfitura nel tubo da quattro pollici e la successiva deflagrazione. Lo riferisce Engineering News-Record.",
   "more": [
    "La corretta mappatura dei sottoservizi e delle tubature di distribuzione del gas è fondamentale per evitare danni accidentali durante i cantieri di scavo. Quando le indicazioni fornite dalle utility sono imprecise, gli strumenti meccanici dei cantieri rischiano di incidere le condotte in pressione, scatenando fughe di gas ad alto rischio di esplosione e incendio nelle aree abitate."
   ],
