   "id": "ze18df08e",
   "sez": "salute",
   "titolo": "La paura di cadere aumenta il rischio di incidenti fisici negli anziani",
   "orig": "Common risks for falling that most Americans overlook",
   "lead": "Negli Stati Uniti uno studio medico evidenzia come la paura di cadere rappresenti un fattore di rischio spesso trascurato dalla popolazione. Il timore di perdere l'equilibrio spinge molte persone a evitare l'uso delle scale, la pratica di esercizi fisici e lo svolgimento delle normali attività quotidiane; tuttavia, questa drastica riduzione del movimento fisico provoca un indebolimento muscolare che aumenta paradossalmente la probabilità di subire incidenti domestici e rovinose cadute. Lo riferisce Medical Xpress.",
   "more": [
    "La sedentarietà indotta dal timore di infortuni altera la capacità di coordinazione e riduce la densità ossea, rendendo l'organismo più vulnerabile alle fratture. I programmi di prevenzione per gli anziani coniugano il rafforzamento motorio con il supporto psicologico per favorire un'attività fisica costante e in sicurezza."
   ],
