   "id": "zdb3aa346",
   "sez": "cultura",
   "titolo": "Portogallo: i comuni dell'Alentejo lanciano il progetto di turismo minerario Min'Arte",
   "orig": "Mértola, Aljustrel e Grândola juntam forças no turismo e património das minas",
   "lead": "In Portogallo i tre comuni alentejani di Mértola, Aljustrel e Grândola hanno unito le proprie forze per lanciare il progetto Min'Arte, un'iniziativa congiunta focalizzata sul turismo sostenibile e la valorizzazione del patrimonio storico-minerario. Il programma mira a riqualificare i territori della Mina de São Domingos, di Aljustrel e del Lousal, integrando attività culturali e percorsi turistici che culmineranno nell'organizzazione di un festival dedicato previsto per l'anno 2028. Lo riferisce Público.",
   "more": [
    "L'archeologia industriale rappresenta un settore in crescita per la rivitalizzazione delle regioni dell'interno europeo colpite dalla chiusura dei siti estrattivi. Riconvertire le ex miniere in poli museali ed ecoturistici consente di preservare la memoria storica delle comunità e di attrarre visitatori, stimolando l'economia locale in modo ecologicamente sostenibile."
   ],
