   "sez": "economia",
   "titolo": "Johannesburg: il settore immobiliare si adatta alle difficoltà comunali",
   "orig": "AFTER THE BELL: Business is betting on a post-ANC Joburg — unless ego gets in the way",
   "lead": "A Johannesburg le principali società del settore immobiliare, tra cui Redefine Properties e Growthpoint, stanno adattando le proprie strategie operative per fronteggiare le gravi disfunzioni amministrative del comune e l'elevato numero di locali commerciali sfitti. Il settore privato scommette su un futuro economico successivo all'era di governo dell'ANC, pur monitorando con cautela l'andamento dei complessi negoziati di coalizione politica locale e la gestione delle infrastrutture urbane della città. Lo riferisce Daily Maverick.",
   "more": [
    "Johannesburg rappresenta il cuore economico della Sudafrica, ma la gestione dei servizi pubblici essenziali soffre da tempo di inefficienze e guasti infrastrutturali. Le grandi imprese immobiliari cercano di preservare il valore dei propri asset orientando gli investimenti verso polo di sviluppo privato meglio gestiti o adottando soluzioni autonome per l'erogazione di acqua ed energia."
   ],
