   "id": "zcbe73bb3",
   "sez": "mondo",
   "titolo": "Ucraina: Zelenskyy avverte sui raid russi ai ponti sul fiume Dnipro",
   "orig": "Russian strikes aim to cut Ukraine in half, Zelenskyy warns",
   "lead": "Il presidente ucraino Volodymyr Zelenskyy ha lanciato un allarme sui continui attacchi condotti dalle forze armate russe contro i ponti strategici che attraversano il fiume Dnipro. Secondo la presidenza di Kiev, l'obiettivo di Mosca sarebbe quello di interrompere i collegamenti di trasporto e le linee di alimentazione elettrica tra l'ovest e l'est dell'Ucraina, colpire le catene di approvvigionamento e dividere di fatto in due parti l'intero territorio nazionale. Lo riferisce Financial Times.",
   "more": [
    "Il fiume Dnipro costituisce la principale barriera geografica dell'Ucraina e una direttrice fondamentale per il trasporto di merci, truppe e risorse energetiche. I ponti che scavalcano il corso d'acqua rappresentano infrastrutture critiche per la tenuta logistica e per l'integrazione economica delle regioni orientali con il resto del Paese in guerra."
   ],
