   "sez": "tech",
   "titolo": "Agenti di intelligenza artificiale per verificare la sicurezza Zero-Trust",
   "orig": "AI Agents Are Testing the Limits of Zero-Trust Security",
   "lead": "Ricercatori internazionali e gruppi di lavoro presso la Queen's University Belfast stanno testando i limiti delle architetture di sicurezza informatica Zero-Trust attraverso l'impiego di task force di agenti di intelligenza artificiale. Coordinati da un orchestratore centrale, gli agenti sviluppano applicazioni per la valutazione dei rischi e la gestione delle informazioni, garantendo il controllo costante dei registri storici per evitare che decisioni pregresse possano condizionare o alterare i processi analitici futuri. Lo riferisce IEEE Spectrum.",
   "more": [
    "Il modello di sicurezza informatica Zero-Trust si basa sul principio di non fidarsi mai di alcun dispositivo o utente, richiedendo una verifica continua di ogni richiesta di accesso alle reti. L'integrazione di agenti autonomi gestiti da intelligenza artificiale permette di automatizzare il monitoraggio e di individuare tempestivamente eventuali anomalie o vulnerabilità nei sistemi aziendali."
   ],
