   "titolo": "Veneto: autorizzate 20 scuole per la filiera formativa 4+2 per il 2027/28",
   "orig": "Filiera 4+2, in Veneto autorizzate 20 scuole per il 2027/28: l’elenco. Accordi di rete entro il 15 dicembre",
   "lead": "In Veneto le autorità scolastiche regionali hanno approvato l'elenco di venti scuole autorizzate ad attivare i percorsi quadriennali della filiera formativa tecnologico-professionale, nota come formula 4+2, per l'anno scolastico 2027/2028. Gli istituti selezionati avranno tempo fino al 15 dicembre per sottoscrivere gli accordi di rete necessari a consolidare l'offerta didattica integrata con gli Istituti Tecnici Superiori e le aziende partner del territorio regionale. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La riforma della filiera tecnologico-professionale 4+2 consente agli studenti di conseguire il diploma di scuola secondary superiore in quattro anni anziché cinque, favorendo un accesso più rapido ai corsi biennali degli ITS Academy. L'iniziativa punta a ridurre il disallineamento tra le competenze richieste dalle imprese regionali e la formazione offerta dal sistema scolastico."
   ],
