   "sez": "musica",
   "titolo": "Paul McCartney è diventato miliardario ed è il terzo musicista più ricco al mondo",
   "orig": "Paul McCartney Is a Billionaire — and the World’s Third-Richest Musician — According to Forbes",
   "lead": "Paul McCartney ha raggiunto lo status di miliardario, posizionandosi come il terzo musicista più ricco del pianeta secondo la classifica di Forbes. L'ex componente dei Beatles ha costruito la sua fortuna non solo grazie a una carriera leggendaria, ma anche investendo strategicamente nei diritti musicali di altri artisti. Questo traguardo finanziario mette in luce la sua influenza duratura e le sue capacità imprenditoriali nell'industria globale dell'intrattenimento, consolidando ulteriormente il suo primato economico oltre che artistico nel mondo della musica. Lo riferisce Billboard.",
   "more": [
    "Raggiungere un patrimonio di un miliardo di dollari è un evento raro per i musicisti, che spesso diversificano le entrate oltre i dischi e i tour. Molti artisti investono in cataloghi musicali, poiché i diritti di pubblicazione generano royalty costanti da streaming, radio e licenze per film o pubblicità, rappresentando asset finanziari estremamente stabili."
   ],
