   "id": "z6b4f44c9",
   "sez": "economia",
   "titolo": "Corea del Nord: il caro grano spinge i contadini verso il debito",
   "orig": "Soaring grain prices bury farm workers in debt",
   "lead": "In Corea del Nord, nella provincia del Hwanghae Settentrionale, l'impennata dei prezzi dei cereali sta travolgendo i lavoratori agricoli, esponendoli a pesanti debiti in vista dell'inverno del 2026. La scorsa primavera, molti contadini avevano preso in prestito cibo e beni di prima necessità impegnandosi a ripagarli con parte del raccolto. Poiché il grano è ora molto più costoso rispetto al momento del prestito, ai contadini resterà pochissimo dopo aver saldato i propri oneri, mettendo a rischio la loro sussistenza alimentare. Lo riferisce Daily NK.",
   "more": [
    "La Corea del Nord affronta storiche difficoltà nell'approvvigionamento alimentare a causa di un'economia pianificata inefficiente e delle sanzioni internazionali. In questo contesto, le fluttuazioni dei prezzi sui mercati non ufficiali possono avere effetti devastanti sui braccianti, che dipendono interamente dal valore dei propri raccolti per sopravvivere."
   ],
