   "id": "zcddf1013",
   "sez": "ambiente",
   "titolo": "Kentucky: un giudice blocca un elettrodotto in una foresta centenaria",
   "orig": "Judge blocks power line through Kentucky college's century-protected forest",
   "lead": "Un tribunale del Kentucky ha emesso una sentenza a favore del Berea College, bloccando il passaggio di una linea elettrica attraverso una foresta protetta da oltre un secolo. Il giudice ha stabilito che la proposta della East Kentucky Power Cooperative non ha analizzato in modo adeguato gli attributi ambientali dell'area boschiva interessata. La decisione ha sottolineato l'importanza del coinvolgimento della comunità locale in questi progetti infrastrutturali. Tuttavia, la battaglia legale non è conclusa, poiché la cooperativa ha già manifestato l'intenzione di impugnare il provvedimento giudiziario. Lo riferisce Times of India.",
   "more": [
    "Le foreste protette di lunga data sono cruciali per la conservazione della biodiversità e agiscono come serbatoi di carbonio. Le dispute tra enti per l'energia e istituzioni locali evidenziano il conflitto tra la necessità di potenziare le infrastrutture elettriche nazionali e l'obbligo legale di tutelare il patrimonio naturale e storico del territorio."
   ],
