   "sez": "salute",
   "titolo": "Un pettine elettrico sperimentale potrebbe curare la calvizie",
   "orig": "Could this experimental electric comb be a cure for baldness?",
   "lead": "Alcuni ricercatori hanno sviluppato un innovativo dispositivo simile a un pettine elettrico che ha prodotto risultati sorprendenti nella stimolazione della crescita dei capelli nei test sui topi. Mentre i trattamenti attuali come il minoxidil e i trapianti offrono gradi variabili di successo, questa nuova tecnologia sperimenta un approccio differente per contrastare la perdita dei capelli. Se i risultati fossero confermati sull'uomo, il dispositivo potrebbe rappresentare una svolta terapeutica in un campo che per millenni ha cercato rimedi efficaci, dai grassi animali dell'antichità alle pillole moderne. Lo riferisce Medical Xpress.",
   "more": [
    "L'alopecia androgenetica è una condizione comune che causa la perdita permanente dei capelli. La ricerca di nuove terapie si sta concentrando sulla stimolazione meccanica o elettrica dei follicoli dormienti, cercando alternative meno invasive rispetto alla chirurgia e più efficaci dei farmaci a uso topico."
   ],
