   "titolo": "Farina 00, 0, 1, 2 e integrale: ecco come cambiano in base alla lavorazione",
   "orig": "Farina 00, 0, 1, 2 e integrale: cosa cambia davvero? Siamo andati in un molino per fare chiarezza",
   "lead": "Un'indagine condotta all'interno di un mulino ha chiarito che le differenze tra le farine di tipo 00, 0, 1, 2 e integrale non dipendono dalla varietà del grano, ma esclusivamente dal metodo di lavorazione del chicco. Ogni tipologia è definita dal grado di raffinazione e dalla presenza di diverse parti del chicco dopo la macinazione. Questo processo determina non solo la consistenza della farina, ma anche le sue proprietà nutrizionali e i possibili utilizzi in ambito gastronomico, dalla panificazione alla pasticceria. Lo riferisce Geopop.",
   "more": [
    "La classificazione delle farine in Italia si basa sulle ceneri, ovvero i minerali che rimangono dopo la combustione, indicando quanto crusca e germe siano presenti. La farina 00 è la più bianca e pura, contenente solo l'endosperma, mentre quella integrale conserva tutte le parti nutrienti del seme."
   ],
