   "sez": "cultura",
   "titolo": "Addio a Gustavo Freiberg, l'artista argentino esule in Brasile",
   "orig": "Mortes: Exilado político da Argentina fez da Vila Madalena seu ateliê",
   "lead": "Esiliato politico per la sua lotta contro la violenza di Stato nel suo Paese d'origine, Freiberg aveva unito la passione per l'arte all'attivismo sociale, partecipando ai movimenti studenteschi e sindacali di ispirazione peronista. La sua vita è stata una testimonianza di resistenza e dedizione culturale, portata avanti attraverso le sue opere e il suo impegno costante nella comunità brasiliana. Lo riferisce Folha de S.Paulo.",
   "more": [
    "Durante gli anni '70 e '80, molti intellettuali e artisti sudamericani furono costretti all'esilio a causa delle dittature militari. San Paolo divenne un centro cruciale per questi rifugiati, favorendo scambi culturali che hanno influenzato profondamente l'arte contemporanea latinoamericana e i movimenti di rivendicazione democratica."
   ],
