   "titolo": "L'artista londinese Soldier firma il nuovo orologio Hublot Big Bang",
   "orig": "Leonard Iheagwam – aka Soldier – is the latest artist to put his stamp on Hublot's Big Bang",
   "lead": "Leonard Iheagwam, noto con lo pseudonimo di Soldier, ha presentato a Londra la sua collaborazione con il marchio svizzero Hublot per la creazione del modello Big Bang Soldier All Black. L'artista ha lavorato per integrare il proprio stile nel design preesistente, con l'obiettivo di rispettare l'eredità dell'orologio introducendo al contempo una nuova narrazione visiva. La collaborazione unisce il mondo dell'arte contemporanea britannica all'eccellenza dell'orologeria di lusso, trasformando un oggetto tecnico in un pezzo d'arte da collezione caratterizzato da un'estetica innovativa e ricercata. Lo riferisce Wallpaper*.",
   "more": [
    "Le collaborazioni tra il settore del lusso e l'arte urbana sono sempre più frequenti, servendo a rinnovare l'immagine di marchi storici e ad attrarre collezionisti più giovani. Hublot, in particolare, è noto per le sue edizioni limitate che fondono materiali all'avanguardia con linguaggi artistici eterogenei."
   ],
