   "titolo": "USA: Scott Wiener pronto a regolare l'IA al Congresso",
   "orig": "Nancy Pelosi’s replacement is ready to regulate AI",
   "lead": "Scott Wiener, dopo aver vinto il seggio lasciato libero da Nancy Pelosi a San Francisco, si prepara a influenzare le politiche federali sull'intelligenza artificiale. Già autore in California di normative volte a limitare i rischi delle IA avanzate, Wiener intende ora portare questa esperienza a Washington. La sua elezione è considerata strategica per la creazione di una regolamentazione nazionale che bilanci l'innovazione con la mitigazione dei pericoli tecnologici, consolidando il suo ruolo di leader legislativo nel campo delle tecnologie emergenti negli Stati Uniti. Lo riferisce MIT Technology Review.",
   "more": [
    "La regolamentazione dell'IA è uno dei temi più caldi negli Stati Uniti, dove si cerca di definire standard di sicurezza senza frenare la competitività tecnologica contro la Cina. Le norme proposte in California sono spesso precursori di leggi federali, influenzando l'intero mercato tech mondiale."
   ],
