   "id": "z90a73166",
   "sez": "cultura",
   "titolo": "Il sovrano Verica potrebbe essere stato una donna? L'ipotesi degli archeologi",
   "orig": "Verica, il re che spinse Roma a invadere la Britannia potrebbe essere stata una donna? Facciamo chiarezza",
   "lead": "L'archeologo Miles Russell ha proposto una nuova interpretazione storica secondo cui Verica, il regnante degli Atrebati che invocò l'aiuto di Roma per l'invasione della Britannia, potrebbe essere stata in realtà una donna. L'ipotesi si fonda sull'analisi di reperti monetali e sull'etimologia del nome. Tuttavia, questa teoria solleva forti perplessità tra molti studiosi del settore, che sottolineano la mancanza di prove certe e le criticità interpretative delle immagini numismatiche del I secolo d.C. La comunità scientifica rimane divisa su questa possibile riscrittura dell'identità del sovrano. Lo riferisce Geopop.",
   "more": [
    "Verica fu una figura chiave del I secolo, un re britannico in esilio che cercò rifugio presso l'imperatore Claudio. La sua richiesta di intervento fornì la giustificazione politica per la conquista romana della Britannia nel 43 d.C., cambiando per sempre la storia dell'isola e dell'Impero."
   ],
