   "sez": "cultura",
   "titolo": "A Quito va in scena 'Las reinas indias' tra opera barocca e resistenza",
   "orig": "‘Las reinas indias’ defienden la historia, el territorio y el agua desde el escenario del Teatro Nacional Sucre",
   "lead": "Dal 12 al 14 novembre, il Teatro Nazionale Sucre di Quito presenta la semi-opera \"Las reinas indias\", una produzione che celebra la storia, il territorio e la difesa dell'acqua. Lo spettacolo intreccia le composizioni barocche di Henry Purcell con le opere di autori latinoamericani contemporanei. Attraverso la musica e la drammaturgia, l'opera intende dare voce alle tematiche della resistenza culturale e della protezione dell'ambiente, creando un ponte tra la tradizione musicale europea e l'identità indigena dell'Ecuador e dell'intera regione. Lo riferisce El Universo.",
   "more": [
    "La semi-opera è un formato teatrale che fonde recitazione, musica e danza. Utilizzare questo genere classico per narrare le lotte dei popoli nativi dell'America Latina permette di attualizzare il repertorio barocco, portando sul palco temi urgenti come la sovranità delle risorse naturali e la conservazione delle culture ancestrali."
   ],
