   "id": "zc646230c",
   "sez": "economia",
   "titolo": "Terzo settore: speciale sul Piano nazionale economia sociale",
   "orig": "Terzo settore: il Piano nazionale economia sociale",
   "lead": "Il 12 novembre sarà distribuito in edicola, in abbinamento al Sole 24 Ore, uno speciale dedicato al Piano nazionale economia sociale. La pubblicazione approfondirà le riforme e le prospettive di crescita del Terzo settore, con un focus sulle nuove normative per le imprese sociali e le organizzazioni non profit. Al costo di 3,50 euro, l'iniziativa si propone di offrire un quadro completo sulle opportunità di sviluppo sostenibile e di impatto sociale in Italia, fornendo strumenti informativi utili per i professionisti del comparto. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "L'economia sociale raggruppa enti che pongono l'interesse collettivo davanti al profitto. In Italia, questo settore è in forte trasformazione grazie alla Riforma del Terzo Settore, che mira a professionalizzare il comparto garantendo trasparenza e semplificando l'accesso ai finanziamenti pubblici e privati per finalità solidali."
   ],
