   "id": "z5fa1d1a0",
   "sez": "salute",
   "titolo": "USA: un pericoloso batterio tropicale del suolo si diffonde nel Mississippi",
   "orig": "Potentially deadly soil bacterium gaining foothold in new regions, including the US",
   "lead": "Un batterio del suolo potenzialmente letale, originario delle zone tropicali, sta guadagnando terreno negli Stati Uniti continentali, con nuovi casi rilevati nel Mississippi. La scoperta solleva interrogativi sulla capacità del sistema sanitario di identificare correttamente queste infezioni e di monitorarne l'espansione. Gli esperti temono che l'agente patogeno possa stabilirsi in nuove regioni a causa di cambiamenti ambientali, rendendo necessaria una maggiore attenzione diagnostica per prevenire malattie gravi o mortali tra la popolazione locale esposta al contatto con il terreno. Lo riferisce Medical Xpress.",
   "more": [
    "L'espansione di batteri tropicali in zone temperate è spesso legata all'aumento delle temperature globali, che permette la sopravvivenza di organismi precedentemente limitati a climi caldi. Patologie come la melioidosi richiedono diagnosi precoci e trattamenti antibiotici specifici per evitare esiti fatali, sfidando i protocolli medici tradizionali delle zone colpite."
   ],
