   "id": "z87349ac6",
   "sez": "tech",
   "titolo": "Beyon Cyber ottiene la certificazione SOC 2 per la sua piattaforma AI",
   "orig": "Beyon Cyber Secures Global AI Attestation",
   "lead": "Orryx AI, una piattaforma di sicurezza basata su intelligenza artificiale sviluppata da Beyon Cyber, ha ottenuto l'attestazione globale SOC 2. Si tratta della prima soluzione di questo tipo nell'area del Consiglio di Cooperazione del Golfo a ricevere tale riconoscimento, che garantisce elevati standard di sicurezza e protezione dei dati. L'attestazione conferma l'affidabilità delle operazioni di cybersicurezza della piattaforma e rappresenta un passo significativo per lo sviluppo tecnologico del Bahrein e della regione nel mercato globale della protezione informatica. Lo riferisce Daily Tribune.",
   "more": [
    "La conformità SOC 2 è uno standard di controllo che assicura che un'organizzazione gestisca i dati dei propri clienti con i massimi criteri di sicurezza, disponibilità e riservatezza. Per le aziende tech, ottenere questa certificazione è un requisito fondamentale per operare con clienti istituzionali e multinazionali su scala globale."
   ],
