   "id": "za992552f",
   "sez": "mondo",
   "titolo": "Gli Stati Uniti espellono il console generale del Libano a Detroit",
   "orig": "US deports Lebanese consul-general in Detroit over Hezbollah praise",
   "lead": "Il segretario di Stato americano Marco Rubio ha ordinato l'espulsione dal territorio statunitense di Ibrahim Charara, console generale del Libano a Detroit. La decisione di allontanare il diplomatico libanese è stata adottata dalle autorità di Washington a seguito di dichiarazioni pubbliche con cui il funzionario avrebbe rivolto elogi al movimento armato libanese Hezbollah. Il provvedimento si inserisce nel quadro delle misure restrittive applicate dagli Stati Uniti contro individui collegati all'organizzazione filo-iraniana. Lo riferisce Al Jazeera.",
   "more": [
    "Hezbollah è un'organizzazione politica e paramilitare sciita libanese fondata negli anni Ottanta e sostenuta dall'Iran. Gli Stati Uniti la considerano formalmente un gruppo terroristico, vietando qualsiasi attività di sostegno o propaganda a suo favore sul suolo nazionale e applicando sanzioni ed espulsioni nei confronti di funzionari che esprimano vicinanza al gruppo."
   ],
