   "id": "z6ebd2def",
   "sez": "mondo",
   "titolo": "L'Iran inasprisce la sicurezza interna di fronte alle minacce di raid statunitensi",
   "orig": "Iran’s authorities harden domestic security controls amid US strike threats",
   "lead": "Le autorità di Teheran hanno deciso di rafforzare le misure di sicurezza interna per fronteggiare il timore di attacchi aerei da parte degli Stati Uniti. Il giro di vite della Repubblica islamica si rivolge verso presunte minacce all'ordine pubblico, colpendo sospette reti di spionaggio e reprimendo i raduni di giovani nelle principali aree urbane del Paese. L'inasprimento dei controlli mira a prevenire contestazioni interne e a blindare le infrastrutture statali in una fase di forte tensione con Washington. Lo riferisce Al Jazeera.",
   "more": [
    "Le tensioni tra Iran e Stati Uniti affondano le radici nel contrasto sul programma nucleare iraniano e sulle dinamiche del Medio Oriente. Nei momenti di attrito militare, Teheran tende a intensificare la vigilanza interna per neutralizzare possibili infiltrazioni esterne e scoraggiare manifestazioni di dissenso popolare contro le istituzioni teocratiche."
   ],
