   "id": "z85e5ce7e",
   "sez": "viaggi",
   "titolo": "Repubblica Ceca, crescono del quattro per cento gli arrivi turistici nel terzo trimestre",
   "orig": "Tourist arrivals in Czechia rise by four percent in third quarter",
   "lead": "Il settore turistico della Repubblica Ceca ha registrato un aumento del quattro per cento nel numero di arrivi durante il terzo trimestre dell'anno. I dati confermano la ripresa e l'attrattività del Paese centroeuropeo nei mesi estivi, trainata sia dai visitatori internazionali sia dal flusso di viaggiatori interni diretti verso le principali mete culturali e le strutture ricettive del territorio. La dinamica positiva consolida il ruolo dell'industria dell'ospitalità come voce rilevante per l'economia nazionale e i servizi collegati ai trasporti. Lo riferisce Radio Prague International.",
   "more": [
    "Il turismo rappresenta una risorsa centrale per la Repubblica Ceca, con la capitale Praga e i siti storici regionali tutelati dall'Unesco capaci di attrarre milioni di viaggiatori ogni anno. La crescita del comparto riflette l'efficacia dei collegamenti ferroviari e aerei continentali e la tenuta dell'offerta ricettiva centroeuropea."
   ],
