   "id": "zb8237b6a",
   "sez": "prima",
   "titolo": "Ex Ilva, corsa a due per l'acquisto con le offerte di Jindal e Arvedi",
   "orig": "Ex Ilva, offerte di Jindal e Arvedi",
   "lead": "La procedura per l'acquisto degli stabilimenti dell'ex Ilva si è chiusa formalmente con la presentazione di due sole offerte, giunte dal gruppo internazionale Jindal e dall'azienda cremonese Arvedi. La società italiana ha scelto di muoversi in autonomia rispetto alla cordata di imprenditori promossa da Federacciai, precisando che la validità della propria proposta è subordinata al consenso della comunità locale di Taranto e delle istituzioni. Il governo e i commissari straordinari dovranno ora valutare la sostenibilità finanziaria, occupazionale e ambientale dei due piani industriali in gara.",
   "more": [
    "L'acciaieria di Taranto costituisce un asset strategico per la manifattura e la produzione industriale italiana, ma da anni richiede interventi urgenti di risanamento e decarbonizzazione dei processi. La cessione dell'impianto punta a garantire la continuità produttiva, preservare migliaia di posti di lavoro e avviare la necessaria transizione ecologica del sito."
   ],
