   "id": "z7f8ce2df",
   "sez": "italia",
   "titolo": "A Perugia apre Pane e Rose, il supermercato con la spesa gratuita per i bisognosi",
   "orig": "A Perugia apre un supermercato dove chi è in difficoltà può fare la spesa gratis",
   "lead": "Nel quartiere Sant'Erminio a Perugia è stato aperto Pane e Rose, un supermercato solidale destinato ad aiutare le persone in condizioni di vulnerabilità economica. Chi si trova in difficoltà può recarsi nel punto vendita e scegliere gratuitamente i prodotti di cui ha bisogno utilizzando una tessera a punti assegnata dai servizi di assistenza. Il progetto sociale non si limita alla distribuzione di generi alimentari, ma include anche l'organizzazione di appositi laboratori di cucina antispreco per sensibilizzare i cittadini a un consumo responsabile del cibo.",
   "more": [
    "Gli empori solidali sono iniziative nate per contrastare la povertà alimentare attraverso un modello rispettoso della dignità delle persone, consentendo agli utenti di scegliere liberamente cosa prendere dagli scaffali anziché ricevere pacchi preconfezionati. Questi progetti si basano sulle donazioni e sul recupero delle eccedenze alimentari della grande distribuzione."
   ],
