   "id": "z0cb8332b",
   "sez": "spazio",
   "titolo": "Conclusa la missione CHAPEA 2 della NASA dopo 378 giorni di simulazione marziana",
   "orig": "CHAPEA Mission 2 Crew Reflects After 378 Days on Simulated Mars",
   "lead": "I quattro ricercatori volontari della missione CHAPEA 2 della NASA hanno lasciato il 31 ottobre l'habitat Mars Dune Alpha, completando con successo 378 giorni di isolamento terrestre per simulare la vita sulla superficie di Marte. Il team, composto da Ross Elder, Ellen Ellis, James Spicer e Matthew Montgomery, ha vissuto all'interno di una struttura di circa 160 metri quadrati stampata in 3D, affrontando la totale assenza di finestre, di comunicazioni in tempo reale e dei suoni del mondo esterno per studiare gli effetti psico-fisici di una spedizione spaziale. Lo riferisce Nasa.",
   "more": [
    "Il programma CHAPEA dell'agenzia spaziale statunitense studia la risposta umana a lunghi periodi di confinamento in condizioni analoghe a quelle delle future missioni su Marte. Le informazioni raccolte su alimentazione, carichi di lavoro e stress psicologico aiuteranno a progettare i moduli abitativi e a pianificare le spedizioni umane del programma Artemis."
   ],
