   "id": "z5edc8a9b",
   "sez": "italia",
   "titolo": "Trasporti, previsto un mese di scioperi per treni, aerei e mezzi pubblici",
   "orig": "Scioperi treni novembre 2026: tutte le date. Coinvolti anche bus, metro e aerei, il calendario completo città per città",
   "lead": "Il mese di novembre si prospetta particolarmente complesso per la mobilità e per chi deve spostarsi sul territorio nazionale, a causa di una fitta sequenza di mobilitazioni sindacali proclamate nei trasporti. Il calendario delle agitazioni coinvolge l'intero comparto dei viaggi, interessando i treni dell'alta velocità e regionali, i collegamenti del trasporto pubblico locale con autobus e metropolitane nelle maggiori città, oltre ai voli aerei. Le giornate di protesta provocheranno disagi e cancellazioni per pendolari e viaggiatori sull'intera rete viaria. Lo riferisce Il Messaggero.",
   "more": [
    "Gli scioperi nel settore dei trasporti in Italia sono regolati dalla legge 146 del 1990, che impone l'obbligo di preavviso e la garanzia di fasce orarie di servizio minimo per tutelare i diritti costituzionali dei cittadini alla mobilità. I sindacati ricorrono alle mobilitazioni per rivendicare rinnovi contrattuali, aumenti salariali e maggiori garanzie di sicurezza sul lavoro."
   ],
