   "id": "z117ddd4c",
   "sez": "prima",
   "titolo": "Possibile attacco informatico alla Dia, avviate verifiche su presunti dossier sottratti",
   "orig": "Possibile attacco hacker alla Dia, verifiche in corso. Piantedosi: 'Non è in atto una emergenza'",
   "lead": "La Direzione investigativa antimafia è al centro di approfondite verifiche tecniche per chiarire la portata di un possibile attacco hacker ai propri server. Un pirata informatico, firmatosi sul dark web con il nome di Weykofa, ha affermato di essere in possesso di 302 file riservati per un archivio di circa 220 megabyte, contenente presunti dossier su gruppi criminali e materiale Europol, chiedendo un riscatto in bitcoin. Il ministro dell'Interno Matteo Piantedosi ha assicurato che al momento non è in corso alcuna emergenza, mentre le istituzioni monitorano con attenzione la minaccia informatica.",
   "more": [
    "Gli attacchi cyber a infrastrutture statali e organi di polizia costituiscono una minaccia crescente nell'ambito della cosiddetta guerra ibrida. La sottrazione di materiale investigativo può esporre a rischi testimoni, informatori e indagini delicate, spingendo le autorità di sicurezza a potenziare costantemente i protocolli di difesa e crittografia delle reti della pubblica amministrazione."
   ],
