   "id": "zb28b9213",
   "sez": "economia",
   "titolo": "Thames Water tratta con i creditori per estendere le scadenze sul debito da 20 miliardi",
   "orig": "Thames Water asks creditors for more time to help repay £20bn debt pile",
   "lead": "La società britannica Thames Water, principale operatore idrico del Regno Unito, ha chiesto ai propri creditori una proroga sui termini di restituzione del proprio debito complessivo, pari a venti miliardi di sterline. Il gruppo ha avanzato una proposta provvisoria volta a spostare dal 2027 al marzo 2028 la scadenza di pagamento di una quota non precisata delle passività iscritte a bilancio, nel tentativo di scongiurare il collasso finanziario e garantire la continuità aziendale.",
   "more": [
    "Thames Water gestisce la fornitura idrica e il trattamento delle acque reflue per milioni di residenti nell'area metropolitana di Londra e nella valle del Tamigi. La combinazione di tassi di interesse elevati, decenni di investimenti insufficienti nelle infrastrutture e forti debiti accumulati ha messo sotto pressione la stabilità finanziaria dell'intero settore dei servizi pubblici nel Paese."
   ],
