   "sez": "cultura",
   "titolo": "L'opera teatrale di Alberto Moravia torna in scena sul palco del Titano",
   "orig": "Dopo i successi Roma e Lecce, \"La vita è gioco\" di Alberto Moravia torna al teatro Titano di San Marino",
   "lead": "L'opera teatrale intitolata «La vita è gioco», scritta dal celebre autore italiano Alberto Moravia, torna sul palcoscenico del teatro Titano nella Repubblica di San Marino. La rappresentazione approda nel teatro sammarinese dopo essere stata allestita con successo di pubblico e critica nelle città italiane di Roma e di Lecce, rinnovando l'interesse per la produzione drammaturgica dello scrittore del Novecento. Lo riferisce San Marino RTV.",
   "more": [
    "Alberto Moravia è stato uno dei più influenti scrittori e intellettuali italiani del ventesimo secolo, celebre per romanzi come «Gli indifferenti» e «La noia». Oltre alla vasta produzione narrativa e giornalistica, l'autore ha esplorato la drammaturgia, componendo testi incentrati sui rapporti interpersonali, sull'alienazione borghese e sul disincanto della società contemporanea."
   ],
