   "id": "z975001fd",
   "sez": "viaggi",
   "titolo": "Turisti e operatori chiedono di mantenere aperto il campeggio di Pachu oltre il festival",
   "orig": "Pachu Harvest Festival draws calls to open campsite beyond festival",
   "lead": "In Bhutan, la seconda edizione del festival del raccolto di Pachu a Phuentshogling ha attirato centinaia di visitatori grazie all'esenzione di ventiquattr'ore dal pagamento della tassa di sviluppo sostenibile. Secondo l'amministrazione distrettuale di Chhukha, la manifestazione segna un nuovo traguardo per il turismo gestito. Tuttavia, numerosi turisti e operatori del settore hanno chiesto alle autorità locali di consentire l'accesso all'area attrezzata per il campeggio comunitario anche al di fuori delle date della rassegna. Lo riferisce Bhutan Broadcasting Service.",
   "more": [
    "Il Bhutan adotta da tempo una politica turistica basata sul principio di alto valore e basso impatto ambientale, regolata dalla Sustainable Development Fee, una tariffa giornaliera imposta ai visitatori stranieri per proteggere il patrimonio naturale e culturale del regno himalayano e finanziare i servizi pubblici locali."
   ],
