   "sez": "musica",
   "titolo": "U2, Bono svela i retroscena sul nuovo album Carnaval De Luz",
   "orig": "U2, Bono rivela la frase del nuovo album che gli altri volevano cancellare",
   "lead": "In vista dell'uscita del nuovo album degli U2 intitolato «Carnaval De Luz», prevista per il tredici novembre, il cantante Bono ha raccontato i retroscena sulla creazione del disco, svelando che i compagni di gruppo intendevano rimuovere una specifica frase da uno dei testi. L'album è stato preceduto dal singolo «The Greatest Show On Earth», brano che gli osservatori interpretano sia come un ricordo nostalgico dei decenni di massimo successo della band sia come una riflessione sul ruolo della musica. Lo riferisce OndaRock.",
   "more": [
    "Gli U2 sono una delle formazioni rock irlandesi più longeve e celebri al mondo, attivi dalla fine degli anni Settanta. Capaci di vendere centinaia di milioni di copie grazie ad album storici e a tournée internazionali negli stadi, il gruppo ha frequentemente unito sperimentazioni sonore a testi di carattere sociale e autobiografico."
   ],
