   "sez": "mondo",
   "titolo": "Crisi in Paraguay: perquisita la casa dell'ex presidente Peña per il crac bancario",
   "orig": "Paraguay, prosegue la crisi politica: perquisita la residenza dell'ex presidente Peña",
   "lead": "Prosegue la crisi istituzionale in Paraguay, dove la procura ha disposto la perquisizione dell'abitazione dell'ex presidente Santiago Peña. Gli inquirenti stanno indagando sui legami tra l'ex capo di Stato, recentemente destituito dal suo incarico, e l'istituto finanziario Ueno Bank, finito al centro di un dissesto e di una pesante truffa. Nel frattempo, il nuovo presidente della Repubblica Pedro Alliana ha annunciato l'intenzione di garantire il rimborso dei risparmiatori danneggiati dal fallimento dell'istituto bancario.",
   "more": [
    "In Paraguay la destituzione di un presidente e la successione del vicepresidente avvengono attraverso procedure costituzionali che coinvolgono il Congresso nazionale. Le crisi innescate da fallimenti di grandi istituti di credito mettono a dura prova la credibilità delle autorità di vigilanza finanziaria e la tenuta economica del Paese sudamericano."
   ],
