   "id": "z39db1305",
   "sez": "tech",
   "titolo": "TikTok cancella oltre 750.000 video in Kenya per violazione delle linee guida",
   "orig": "Kenya: TikTok Removes 750,000 Videos in Kenya Over Content Violations",
   "lead": "Nel corso del secondo trimestre dell'anno la piattaforma di video brevi TikTok ha rimosso più di 750.000 contenuti in Kenya per aver violato le linee guida della comunità. Il provvedimento testimonia il crescente impegno normativo e operativo a cui sono chiamate le grandi piattaforme digitali in Africa, in un contesto in cui la fruizione di filmati online e l'attività degli utenti sui social network registrano una forte espansione in tutto il territorio keniota.",
   "more": [
    "Le piattaforme social applicano sistemi di moderazione automatica tramite algoritmi affiancati da team di revisori umani per individuare e cancellare contenuti vietati, quali disinformazione, violenza, incitamento all'odio e pedopornografia, nel rispetto delle leggi dei singoli Stati in cui operano."
   ],
