   "id": "z602404a2",
   "sez": "italia",
   "titolo": "Salvini sulle nomine per l'Anac: occorre scegliere con cura senza fretta",
   "orig": "Salvini: 'Sull'Anac è importante scegliere bene e non in fretta'",
   "lead": "Il vicepresidente del Consiglio e ministro delle Infrastrutture Matteo Salvini è intervenuto sulla questione dei vertici dell'Autorità Nazionale Anticorruzione, affermando che nella scelta dei componenti dell'organismo è fondamentale individuare i profili giusti con la dovuta attenzione piuttosto che agire in modo affrettato. Il ministro ha spiegato che gli uffici competenti e le forze politiche stanno lavorando al dossier per giungere a una decisione condivisa per la presidenza dell'autorità di vigilanza. Lo riferisce ANSA.",
   "more": [
    "L'Autorità Nazionale Anticorruzione (Anac) è un organo collegiale indipendente incaricato di prevenire la corruzione nella pubblica amministrazione, vigilare sui contratti pubblici e garantire la trasparenza degli appalti in Italia. La designazione dei suoi membri richiede intese istituzionali e passaggi parlamentari previsti dalla legge."
   ],
