   "id": "zd282c06d",
   "sez": "adolescenti",
   "titolo": "Come le foche si sono evolute per ascoltare sia sopra che sotto l'acqua",
   "orig": "Seals long ago evolved to hear above the water — and below",
   "lead": "I ricercatori hanno svelato il meccanismo biologico che consente alle foche di sentire perfettamente i suoni sia nell'aria che nelle profondità marine. Attraverso scansioni a raggi X condotte su centinaia di campioni auricolari di foche e di altri animali, gli scienziati hanno osservato un particolare tessuto spugnoso che si riempie rapidamente di sangue. Questa specifica struttura anatomica, frutto di un lungo percorso evolutivo, compensa la pressione subacquea permettendo un udito efficiente in entrambi gli ambienti. Lo riferisce Science News Explores.",
   "more": [
    "I mammiferi marini discendono da antenati terrestri e nel corso di milioni di anni hanno sviluppato adattamenti anatomici complessi per muoversi e cacciare nell'acqua. La trasmissione delle onde sonore nei liquidi avviene con velocità e densità differenti rispetto all'aria, richiedendo modifiche agli apparati timpanici."
   ],
