   "id": "z9c09f668",
   "sez": "prima",
   "titolo": "Ungheria, fermato Áron Orbán: l'ex premier denuncia un attacco politico",
   "orig": "Fratele lui Viktor Orbán a fost reținut, anunță premierul Péter Magyar. Fostul prim-ministru acuză că el este „ținta”",
   "lead": "In Ungheria è stato fermato Áron Orbán, fratello dell'ex primo ministro Viktor Orbán, nell'ambito di un'indagine giudiziaria per presunto traffico di esseri umani e facilitazione nell'ottenimento illecito di visti d'ingresso a cittadini stranieri. La notizia è stata resa nota lunedì mattina dal capo del governo ungherese Péter Magyar, che ha confermato che gli accertamenti sono in corso. Viktor Orbán ha reagito parlando di uno sporco gioco politico orchestrato nei suoi confronti e ha accusato le autorità di aver colpito suo fratello per danneggiare direttamente lui.",
   "more": [
    "Il panorama politico ungherese è caratterizzato da forti contrapposizioni tra la maggioranza di governo e le forze d'opposizione. Le indagini su presunte violazioni legate al rilascio di visti e alla gestione dei flussi migratori assumono una forte rilevanza pubblica a causa delle rigide normative ungheresi in materia di immigrazione e controllo delle frontiere."
   ],
