   "id": "z7f1baa05",
   "sez": "mondo",
   "titolo": "Houston, il sindaco ordina alla polizia di limitare la collaborazione con l'agenzia d'immigrazione",
   "orig": "Texas mayor instructs police to limit co-operation with ICE",
   "lead": "Negli Stati Uniti, il sindaco della città texana di Houston ha dato istruzioni alla polizia locale di ridurre la collaborazione operativa con l'ICE, l'agenzia federale responsabile dell'immigrazione e della sicurezza delle frontiere. Il provvedimento mira a circoscrivere l'assistenza municipale alle operazioni federali. Lo riferisce BBC News.",
   "more": [
    "Negli Stati Uniti i rapporti tra le forze di polizia locali e le agenzie federali per l'immigrazione variano a seconda delle ordinanze comunali e delle leggi statali. Alcune città scelgono politiche di cooperazione limitata per evitare che i residenti stranieri non si rivolgano ai servizi essenziali o alla giustizia per paura di espulsioni."
   ],
