   "sez": "mondo",
   "titolo": "Trump a 60 Minutes: «La guerra in Ucraina finirà presto, ma i confini cambieranno»",
   "orig": "Trump says Ukraine will ‘end up with a little bit different shape’ once the war ends",
   "lead": "In un'intervista rilasciata al programma televisivo 60 Minutes dell'emittente statunitense Cbs, il presidente Donald Trump ha dichiarato che il conflitto tra Russia e Ucraina è destinato a concludersi a breve e che la sua fine avverrà grazie alla propria mediazione. Trump ha affermato che a suo avviso il principale ostacolo alla cessazione delle ostilità è l'odio reciproco tra Vladimir Putin e Volodymyr Zelensky, aggiungendo che al termine della guerra l'Ucraina avrà con ogni probabilità confini e una forma territoriale leggermente diversi rispetto al passato.",
   "more": [
    "Le posizioni espresse dalla presidenza statunitense sui confini ucraini toccano il principio dell'integrità territoriale internazionalmente riconosciuto. I colloqui di pace promossi da mediatori internazionali cercano di conciliare la cessazione dei combattimenti con le richieste di sovranità avanzate da Kiev sui territori attualmente sotto controllo militare russo."
   ],
