   "sez": "mondo",
   "titolo": "Myanmar, il governo d'opposizione mette in guardia Washington sulle relazioni con la giunta",
   "orig": "Myanmar’s NUG Warns US Against Prioritizing Its Interests Over Peace",
   "lead": "Il Governo di Unità Nazionale del Myanmar, che rappresenta l'opposizione civile alla dittatura militare, ha lanciato un monito agli Stati Uniti contro la nuova strategia diplomatica di Washington. Secondo l'opposizione democratica birmana, l'impostazione statunitense rischierebbe di accantonare i principi di democrazia e federalismo privilegiando gli interessi economici e un progressivo avvicinamento alla giunta al potere. Gli oppositori chiedono all'amministrazione americana di non sacrificare i diritti civili e le prospettive di una pace duratura in cambio di vantaggi strategici. Lo riferisce The Irrawaddy.",
   "more": [
    "Dal colpo di Stato militare del 2021 il Myanmar vive una grave crisi civile e umanitaria, con scontri estesi tra le forze della giunta e le milizie della resistenza democratica. Il Governo di Unità Nazionale opera in gran parte in clandestinità e dall'estero per mantenere il supporto politico e le sanzioni della comunità internazionale."
   ],
