   "id": "z079228bf",
   "sez": "dibattito",
   "titolo": "Unione Europea, le mobilitazioni giovanili evidenziano la frattura tra Est e Ovest",
   "orig": "Youth protests highlight EU’s split between a restive west and peaceful east",
   "lead": "Nell'Unione Europea si manifesta una divergenza generazionale e politica tra l'Europa occidentale e quella orientale di fronte alla crisi economica e sociale. In nazioni come Francia e Germania ampie fasce di giovani scendono in piazza per contestare la classe dirigente e chiedere interventi urgenti contro l'inflazione e la precarietà, mentre in Paesi dell'Est come la Croazia non si registrano mobilitazioni simili. Chi protesta invoca maggiori tutele economiche e stipendi dignitosi; i governi occidentali lamentano margini di bilancio ristretti per concedere aumenti immediati.",
   "more": [
    "Le disuguaglianze economiche e la diversa fiducia nei confronti delle istituzioni incidono sulla propensione alla mobilitazione collettiva all'interno dell'Unione europea. Nei Paesi occidentali il carovita e le riforme del lavoro suscitano reazioni sindacali strutturate, mentre in diversi Stati dell'Est la memoria di recenti transizioni economiche e la frammentazione sindacale generano dinamiche differenti."
   ],
